"""Summarize committed offline evidence; verify the static page matches disk."""
import hashlib,json,re,urllib.request
from pathlib import Path
root=Path(__file__).resolve().parents[1]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
corpora=[]
for name in ['command-limits','calendar-waits']:
 p=root/'test/fixtures'/f'{name}-reference.json';d=json.loads(p.read_text());steps=[s for c in d['cases'] for s in c['steps']];draws=[r for s in steps for r in s['random']]
 corpora.append(dict(name=name,fixture=str(p.relative_to(root)),sha256=sha(p),protocol=d['protocol'],cases=len(d['cases']),checkpoints=len(steps),draws=len(draws),random_reads=sum(len(r['reads'])for r in draws),controlled_setups=[dict(case=i,setup=c['setup'])for i,c in enumerate(d['cases'])if c.get('setup')],printer_rows_compared=sum(len(s.get('paper',[]))for s in steps)))
served=[]
for rel in ['index.html','src/app.mjs','src/game.mjs','src/player-program.mjs','src/virtual-printer.mjs','src/session.mjs','src/spectrum.mjs','src/npc-runtime.mjs','src/random-display.mjs','src/world.mjs','src/text.mjs']:
 with urllib.request.urlopen('http://127.0.0.1:8768/'+rel,timeout=10)as response:body=response.read();cache=response.headers.get('Cache-Control')
 p=root/rel;equal=body==p.read_bytes();assert equal,rel
 served.append(dict(path=rel,sha256=sha(p),served_equal=True,cache_control=cache))
log=(root/'results/command-limits/tests.log').read_text();counts={k:int(re.search(r'ℹ '+k+r' (\d+)',log).group(1))for k in ['tests','pass','fail']};assert counts['tests']==counts['pass']==648 and counts['fail']==0
report=dict(date='2026-10-27',engine='autonomous JavaScript world-v5',full_game_equivalence=False,status='bounded point-6 implementations verified',runtime_uses_original_cpu=False,corpora=corpora,comparison=['every random draw, read address/value and successor','all actor slots, entity fields and facts via assertOriginalState','all 752 arena bytes, including released records','input/editor/token state, exact upper/lower bitmap and owned scratch fields','literal, printer flag and exact printer raster paper','portable save/load roundtrip and future commands'],listing=json.loads((root/'results/command-limits/listing-verification.json').read_text()),tests={**counts,'log':'results/command-limits/tests.log','browser_packet_histories':24,'asynchronous_pause_and_printer_tests':2},browser=dict(url='http://127.0.0.1:8768/',isolated_test_tab=True,user_game_reset=False,sequence=['PAUSE (separate key resumes at 08:00)','PRINT','I (08:01)','NOPRINT (blank upper, still 08:01)','download printer SVG','SAVE (JSON download confirmed, 08:02)','QUIT (frozen at 08:02)'],screenshot='results/command-limits/browser.png',served=served),peripheral_protocol=dict(printer_presence='C03B port input, present/absent declared per case',printer_scan='C40C port input 192, native scan and printer loop preserved',save='C040 transport success stub with carry; native scheduler/control path compared',load='browser JSON adapter, no native tape equivalence claimed'),limits=['seed 1 / graphics off / explicit key and immediate MORE protocol; no universal seed or input-timing parity','controlled calendar/tick/entity setups are not naturally reached play histories','SAVE downloads portable JSON at next prompt; compound rest-of-line may already have run','LOAD cancellation retains current portable game; native tape loader/restart state not reconstructed','QUIT freezes before native restart service','PAUSE and screen clearing use Spectrum presentation; modern notebook keeps transcript','compound WAIT and historical profiles retain prior precomputed frame path','every long vehicle stay and remaining renderer ownership boundaries are point-7 work'])
(root/'results/command-limits-verification.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(dict(tests=counts,corpora=[{k:c[k]for k in ['name','cases','checkpoints','draws','random_reads']}for c in corpora],served_equal=len(served)),indent=2))
